class CustomerOperationsScreen extends StatefulWidget{const CustomerOperationsScreen({super.key});@override State<CustomerOperationsScreen> createState()=>_CustomerOperationsScreenState();}
class _CustomerOperationsScreenState extends State<CustomerOperationsScreen>{TripOperationsRepository? _repo;List<MobileTrip> _trips=[];bool _busy=true;String? _error;
 @override void didChangeDependencies(){super.didChangeDependencies();if(_repo==null){_repo=TripOperationsRepository(AppController.of(context).apiClient);_load();}}
